  'soccer:uefa.champions':'#0e1e5b','soccer:uefa.europa':'#ff6900','soccer:uefa.europa.conf':'#00be14',
  'soccer:usa.1':'#00529b','soccer:usa.nwsl':'#c72c41','basketball:nba':'#17408b','basketball:wnba':'#f15a24',
